import java.util.Scanner;

public class Main {
    static int mod;
    static int[] fr = new int[100005];
    static int[] infr = new int[100005];
    static int[] inv = new int[100005];

    static class Pt {
        long f, g;

        Pt(long f, long g) {
            this.f = f;
            this.g = g;
        }

        Pt add(Pt y) {
            return new Pt(addmod(this.f + y.f), addmod(this.g + y.g));
        }

        Pt mul(Pt y) {
            long newF = (this.f * y.f) % mod;
            long newG = (this.f * y.g + this.g * y.f) % mod;
            return new Pt(newF, newG);
        }
    }

    static int addmod(int x) {
        return x >= mod ? x - mod : x;
    }

    static int submod(int x) {
        return x < 0 ? x + mod : x;
    }

    static long fpow(long x, int y) {
        long ans = 1;
        while (y > 0) {
            if ((y & 1) == 1) {
                ans = (ans * x) % mod;
            }
            x = (x * x) % mod;
            y >>= 1;
        }
        return ans;
    }

    static int F(int x) {
        long res = (long) x * (x + 1) / 2 % mod;
        return (int) res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod = sc.nextInt();

        fr[0] = 1;
        infr[0] = 1;
        for (int i = 1; i <= 100000; i++) {
            fr[i] = (int) ((long) i * fr[i - 1] % mod);
            infr[i] = (int) fpow(fr[i], mod - 2);
            inv[i] = (int) fpow(i, mod - 2);
        }

        Pt[] dp = new Pt[n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i] = new Pt(0, 0);
        }
        dp[0] = new Pt(1, 0);

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                Pt nw = dp[j - 1].mul(dp[i - j]);
                long gVal = (nw.g * (i + 1)) % mod;
                gVal = (gVal + (nw.f * (addmod(F(j - 1) + F(i - j)))) % mod) % mod;
                nw.g = addmod((int) gVal);
                nw.g = (nw.g * inv[i]) % mod;
                long fVal = (nw.f * (i + 1)) % mod;
                fVal = (fVal * inv[i]) % mod;
                nw.f = fVal;
                dp[i] = dp[i].add(nw);
            }
        }

        Pt[][] up = new Pt[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                up[i][j] = new Pt(0, 0);
            }
        }
        up[0][0] = new Pt(1, 0);

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i, m); j++) {
                if (i == j) {
                    up[i][j] = dp[i];
                }
                for (int k = 0; k < j && k < i; k++) {
                    up[i][j] = up[i][j].add(dp[k].mul(up[i - k - 1][j - k]));
                }
            }
        }

        long ans = (up[n][m].g * fr[m]) % mod;
        System.out.println(ans);
        sc.close();
    }
}
